class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        int m = num1.length();
        int n = num2.length();
        int[] result = new int[m + n];

        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                int product = (num1.charAt(i) - '0') * (num2.charAt(j) - '0');
                int p1 = i + j;
                int p2 = i + j + 1;
                int sum = product + result[p2];
                result[p2] = sum % 10;
                result[p1] += sum / 10;
            }
        }

        StringBuilder answer = new StringBuilder();
        for (int digit : result) {
            if (answer.length() == 0 && digit == 0) {
                continue;
            }
            answer.append(digit);
        }
        return answer.length() == 0 ? "0" : answer.toString();
    }
}

class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        String answer = "0";
        int trailingZeros = 0;
        for (int i = num2.length() - 1; i >= 0; i--, trailingZeros++) {
            String partial = multiplyByDigit(num1, num2.charAt(i) - '0', trailingZeros);
            answer = addStrings(answer, partial);
        }
        return answer;
    }

    private String multiplyByDigit(String num, int digit, int trailingZeros) {
        if (digit == 0) {
            return "0";
        }

        StringBuilder reversed = new StringBuilder();
        for (int i = 0; i < trailingZeros; i++) {
            reversed.append('0');
        }

        int carry = 0;
        for (int i = num.length() - 1; i >= 0; i--) {
            int product = (num.charAt(i) - '0') * digit + carry;
            reversed.append((char) ('0' + product % 10));
            carry = product / 10;
        }
        while (carry > 0) {
            reversed.append((char) ('0' + carry % 10));
            carry /= 10;
        }
        return reversed.reverse().toString();
    }

    private String addStrings(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += a.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += b.charAt(j--) - '0';
            }
            reversed.append((char) ('0' + sum % 10));
            carry = sum / 10;
        }
        return reversed.reverse().toString();
    }
}

class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        int m = num1.length();
        int n = num2.length();
        int[] reversed = new int[m + n];

        for (int i = m - 1; i >= 0; i--) {
            int a = num1.charAt(i) - '0';
            for (int j = n - 1; j >= 0; j--) {
                int b = num2.charAt(j) - '0';
                int reversedIndex = (m - 1 - i) + (n - 1 - j);
                reversed[reversedIndex] += a * b;
            }
        }

        StringBuilder digits = new StringBuilder();
        int carry = 0;
        for (int value : reversed) {
            int total = value + carry;
            digits.append((char) ('0' + total % 10));
            carry = total / 10;
        }
        while (carry > 0) {
            digits.append((char) ('0' + carry % 10));
            carry /= 10;
        }
        while (digits.length() > 1 && digits.charAt(digits.length() - 1) == '0') {
            digits.deleteCharAt(digits.length() - 1);
        }
        return digits.reverse().toString();
    }
}

class Solution {
    private static final int BASE = 10000;
    private static final int WIDTH = 4;

    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }

        int[] a = toChunks(num1);
        int[] b = toChunks(num2);
        long[] product = new long[a.length + b.length];

        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < b.length; j++) {
                product[i + j] += 1L * a[i] * b[j];
            }
        }

        long carry = 0;
        for (int i = 0; i < product.length; i++) {
            long total = product[i] + carry;
            product[i] = total % BASE;
            carry = total / BASE;
        }

        int last = product.length - 1;
        while (last > 0 && product[last] == 0) {
            last--;
        }

        StringBuilder answer = new StringBuilder();
        answer.append(product[last]);
        for (int i = last - 1; i >= 0; i--) {
            String chunk = Long.toString(product[i]);
            for (int pad = chunk.length(); pad < WIDTH; pad++) {
                answer.append('0');
            }
            answer.append(chunk);
        }
        return answer.toString();
    }

    private int[] toChunks(String num) {
        int chunkCount = (num.length() + WIDTH - 1) / WIDTH;
        int[] chunks = new int[chunkCount];
        int index = 0;
        for (int end = num.length(); end > 0; end -= WIDTH) {
            int start = Math.max(0, end - WIDTH);
            int value = 0;
            for (int i = start; i < end; i++) {
                value = value * 10 + (num.charAt(i) - '0');
            }
            chunks[index++] = value;
        }
        return chunks;
    }
}

class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }
        return multiplyPositive(num1, num2);
    }

    private String multiplyPositive(String a, String b) {
        a = trim(a);
        b = trim(b);
        if (a.equals("0") || b.equals("0")) {
            return "0";
        }
        if (Math.max(a.length(), b.length()) <= 4) {
            return multiplySmall(a, b);
        }

        int n = Math.max(a.length(), b.length());
        int half = n / 2;

        String lowA = suffix(a, half);
        String highA = prefix(a, half);
        String lowB = suffix(b, half);
        String highB = prefix(b, half);

        String z0 = multiplyPositive(lowA, lowB);
        String z2 = multiplyPositive(highA, highB);
        String z1 = multiplyPositive(add(lowA, highA), add(lowB, highB));
        String middle = subtract(subtract(z1, z2), z0);

        return trim(add(add(shift(z2, 2 * half), shift(middle, half)), z0));
    }

    private String multiplySmall(String a, String b) {
        long left = 0;
        long right = 0;
        for (int i = 0; i < a.length(); i++) {
            left = left * 10 + (a.charAt(i) - '0');
        }
        for (int i = 0; i < b.length(); i++) {
            right = right * 10 + (b.charAt(i) - '0');
        }
        return Long.toString(left * right);
    }

    private String suffix(String value, int width) {
        int start = Math.max(0, value.length() - width);
        return value.substring(start);
    }

    private String prefix(String value, int lowWidth) {
        int end = Math.max(0, value.length() - lowWidth);
        return end == 0 ? "0" : value.substring(0, end);
    }

    private String shift(String value, int zeros) {
        value = trim(value);
        if (value.equals("0")) {
            return "0";
        }
        StringBuilder shifted = new StringBuilder(value);
        for (int i = 0; i < zeros; i++) {
            shifted.append('0');
        }
        return shifted.toString();
    }

    private String add(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += a.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += b.charAt(j--) - '0';
            }
            reversed.append((char) ('0' + sum % 10));
            carry = sum / 10;
        }
        return reversed.reverse().toString();
    }

    private String subtract(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int borrow = 0;
        while (i >= 0) {
            int digit = a.charAt(i--) - '0' - borrow;
            if (j >= 0) {
                digit -= b.charAt(j--) - '0';
            }
            if (digit < 0) {
                digit += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }
            reversed.append((char) ('0' + digit));
        }
        return trim(reversed.reverse().toString());
    }

    private String trim(String value) {
        int index = 0;
        while (index + 1 < value.length() && value.charAt(index) == '0') {
            index++;
        }
        return value.substring(index);
    }
}
